// Seeds come from scripts/fetch-builtins.mjs — lockfile-pinned, sha256-verified
// release artifacts, cached in node_modules/.cache/motrix-builtins after the
// first fetch (repeat runs are offline).

function rebuild(target) {
  const cmd =
    target === 'node'
      ? ['pnpm', ['rebuild', 'better-sqlite3']]
      : [
          'pnpm',
          ['exec', 'electron-rebuild', '--force', '--only', 'better-sqlite3'],
        ]
  const r = spawnSync(cmd[0], cmd[1], { stdio: 'inherit' })
  if (r.error) {
    console.error(`[ensure-native-abi] failed to spawn ${cmd[0]}:`, r.error)
    return 1
  }
  return r.status ?? 0
}

